require'json';require'fileutils';root=File.expand_path('..',__dir__);raw=File.join(root,'work/audit/logreal02-hall-raw.json');system('ruby',File.join(root,'tools/analyze_runtime_logs.rb'),'logs/hall',raw)or abort;source=JSON.parse(File.read(raw));rules={login:{pattern:/账号|account|登录|bindPlayer|Origin/i,tasks:%w[AUTH01 PROTO12]},hall:{pattern:/HALL|game.?catalog|大厅/i,tasks:%w[CALL02 DRIFT03]},club:{pattern:/club|亲友圈/i,tasks:%w[CALL04 CON09]},room:{pattern:/room|房间/i,tasks:%w[CALL05 ROOM01]},asset:{pattern:/currency|gold|diamond|roomcard|sportspoint|钻石|房卡|资产/i,tasks:%w[BILL01 CON09]}};mappings=rules.transform_values{|rule|matches=source.fetch('signatures').select{|row|row.fetch('signature').match?(rule[:pattern])};{tasks:rule[:tasks],signatureCount:matches.length,occurrences:matches.sum{|m|m.fetch('count')},fingerprints:matches.map{|m|m.fetch('fingerprint')}}};checks={hall_log_scanned:source.dig('summary','files')==1,all_domains_mapped:mappings.keys.sort==rules.keys.sort,all_domains_have_runtime_clues:mappings.values.all?{|m|m[:signatureCount]>0},fingerprinted:source.fetch('signatures').all?{|row|row.fetch('fingerprint').length==16}};result={task:'LOGREAL02',passed:checks.values.all?,checks:checks,summary:source.fetch('summary'),domainMappings:mappings,signatures:source.fetch('signatures'),warning:'Historical hall logs map clues to remediation tasks; they do not prove current defects or fixes.'};out=File.join(root,'docs/generated/logreal02-hall.json');FileUtils.mkdir_p(File.dirname(out));File.write(out,JSON.pretty_generate(result)+"\n");abort("LOGREAL02 failed: #{checks}")unless result[:passed]
